"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2242-01-01:1":{"b": ["Primeiro Período Intermédio: começa", "ef148434"], "d": ["Período fragmentado, da dissolução da autoridade central do Império Antigo até ao início do Império Médio; o artigo sublinha a concordância com o evento de seca de 4,2 ka (cerca de 2250 a.C.).", "47a3a1aa"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2499-01-01:0":{"b": ["Reino/cultura de Kerma (Cuxe): começa", "f7cdc981"], "d": ["Reino da Núbia centrado em Kerma, a jusante da Terceira Catarata; passando pelas fases Kerma Antigo (~2500), Médio e Clássico, termina em ~1450 a.C. Honegger 2005: 'Kerma Classique (vers 1500 av. J.-C.)' povoado cercado.", "5ea1ab25"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-2662-01-01:0":{"b": ["Império Antigo (Idade das Pirâmides): começa", "9e3a1499"], "d": ["Reino da Idade das Pirâmides; segundo Erdil e outros 2025, o início do Império Antigo é ~2698–2629 a.C. (95%), a transição para o Primeiro Período Intermédio ~2283–2204 a.C. (95%). A cronologia «Low» já não é apoiada neste intervalo.", "2ac5035a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3125-01-01:0":{"b": ["Cultura Naqada: termina", "a6d98d7b"], "d": ["Cultura pré-dinástica do Alto Egito posterior a Badari; abrange as fases Naqada I-III e, em Naqada IIIC, chega à unificação política com a 1.ª Dinastia (Aha).", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3499-01-01:0":{"b": ["Cultura Pré-Kerma (Pre-Kerma): começa", "35f09768"], "d": ["Cultura que, na região de Kerma (Dongola Reach/Nilo a jusante da Terceira Catarata), faz a passagem do Neolítico para Kerma e mostra fossas de armazenamento agrícola e complexidade social inicial.", "f9a036cb"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3755-01-01:0":{"b": ["Cultura Naqada: começa", "1960a726"], "d": ["Cultura pré-dinástica do Alto Egito posterior a Badari; abrange as fases Naqada I-III e, em Naqada IIIC, chega à unificação política com a 1.ª Dinastia (Aha).", "8fadb99a"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-3949-01-01:0":{"b": ["Abrigo rochoso de Takarkori (Tadrart Acacus): termina", "845c6a70"], "d": ["Abrigo rochoso em Tadrart Acacus, no Fezzan líbio: estratigrafia contínua desde os caçadores-recoletores-pescadores do Acacus Final (LA1, primeiro povoamento) até aos pastores do Pastoril Antigo, Médio e Final (Saara verde).", "29888604"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4699-01-01:0":{"b": ["Neolítico de Esh-Shaheinab (Shaheinab): começa", "7a9cfd9c"], "d": ["Povoado neolítico no Sudão Central, perto do Nilo (animais domésticos, cerâmica, escopro/goiva); define, como sítio-tipo, o «Neolítico de Shaheinab». Intervalo geral da cultura 5000–3800 BCE.", "cd4d3a3c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4849-01-01:0":{"b": ["Povoamento holocénico do Faium (arredores do Lago Qarun): termina", "53ff4e34"], "d": ["No Faium, povoamento holocénico de pescadores-caçadores desde ~7350 a.C.; plantas e animais domésticos desde cerca de 5400 a.C.; povoados neolíticos de Kom K/W 4850–4250 a.C.", "a016950f"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-4999-01-01:0":{"b": ["Cartum Antigo (Mesolítico de Cartum): termina", "89b30a20"], "d": ["Mesolítico de caçadores-recoletores-pescadores com cerâmica (linha ondulada) na margem do Nilo, no Sudão Central; denominado «Khartoum Mesolithic» / «Early Khartoum» por Arkell.", "7c5ed92c"]},
"OLAYLAR_ARKEOLOJI_MISIR_NIL_SAHRA:-7349-01-01:0":{"b": ["Povoamento holocénico do Faium (arredores do Lago Qarun): começa", "eb514aa9"], "d": ["No Faium, povoamento holocénico de pescadores-caçadores desde ~7350 a.C.; plantas e animais domésticos desde cerca de 5400 a.C.; povoados neolíticos de Kom K/W 4850–4250 a.C.", "a016950f"]},
